"""Shared identity and email-safe HTML. Logo is embedded, never remotely tracked."""
from html import escape

LOGO = ''  # Filled from the same circle/pulse geometry as the public header.

def attachments():
    return [{'filename':'tradersecho-pulse.png','content':LOGO,'content_id':'tradersecho-pulse','content_type':'image/png'}]

def header(preview=False):
    logo='data:image/png;base64,'+LOGO if preview else 'cid:tradersecho-pulse'
    return f'''<table role="presentation" cellspacing="0" cellpadding="0"><tr><td style="padding-right:14px"><img src="{logo}" alt="Traders Echo" width="52" height="52" style="display:block;border:0"></td><td><div style="font-size:25px;font-weight:bold;color:#f5f8ee">traders<span style="color:#c4f27a">echo</span></div><div style="font-size:9px;letter-spacing:1.4px;color:#adc5b8;margin-top:7px">ATTENTION · PERSPECTIVE · COMMUNITY</div></td></tr></table>'''

def message(subject,text,body=None,preview=False):
    content=body or '<p style="white-space:pre-line;line-height:1.8">'+escape(text)+'</p>'
    html=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#e7ede5;font-family:Arial,sans-serif;color:#203b2e"><table role="presentation" width="100%"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="600" style="width:100%;max-width:600px;background:#fbfcf8" cellspacing="0" cellpadding="0"><tr><td style="background:#102b24;padding:30px 28px">{header(preview)}</td></tr><tr><td style="padding:32px 28px"><h1 style="font-size:27px;line-height:1.3;color:#153c30">{escape(subject)}</h1>{content}</td></tr><tr><td style="padding:24px 28px;border-top:1px solid #dde5df;color:#617562;font-size:12px;line-height:1.8">Traders Echo · AI supply-chain research<br><a href="mailto:info@tradersecho.com" style="color:#365644">info@tradersecho.com</a><br>Attention is context, not investment advice.</td></tr></table></td></tr></table></body></html>'''
    return {'subject':subject,'text':text,'html':html,'attachments':[] if preview else attachments()}

def trial_reminder(user,origin,preview=False):
    from datetime import datetime
    from zoneinfo import ZoneInfo
    end=datetime.fromtimestamp(user['trial_ends_at'],ZoneInfo('America/New_York')).strftime('%b %d, %Y at %I:%M %p %Z')
    subject='Your Traders Echo Premium trial ends soon'
    plans=origin.rstrip('/')+'/plans'
    text=f"Hi {user['display_name']}, your Premium trial ends {end}. Keep your full rankings, personal voices and Trading room access with Premium ($19/month or $190/year), or Founder ($999 once, while the service operates). No automatic charge: otherwise your account returns to Free. Choose your plan: {plans}"
    tiles=''
    for title,price,detail in [('Premium','$19/month or $190/year','Full rankings, 50 saved stocks, up to 5 personal voices and the Trading room. Recurring billing; cancel renewal anytime.'),('Founder','$999 once','Premium access while Traders Echo operates, plus your Founder badge. Same usage limits as Premium. No renewal.')]:
        tiles+=f'<div style="background:#183d30;border-radius:12px;padding:26px 24px;margin:18px 0;color:#eef4e8"><h2 style="color:#c4f27a;margin:0 0 14px">{title}</h2><strong style="font-size:24px">{price}</strong><p style="line-height:1.8;font-size:14px">{detail}</p><a href="{escape(plans)}" style="display:inline-block;background:#c4f27a;color:#143b28;text-decoration:none;padding:14px 20px;border-radius:6px;font-weight:bold">Explore {title} →</a></div>'
    body=f'<p style="line-height:1.8">Hi {escape(user["display_name"])}, your Premium trial ends <strong>{escape(end)}</strong>. Keep the research tools you’ve been exploring.</p>{tiles}<p style="line-height:1.8">No card was required for your trial, and there is no automatic charge. If you do nothing, your account returns to Free. All prices in USD.</p><p><a href="{escape(origin)}/account">Manage email preferences</a></p>'
    return message(subject,text,body,preview)
